\begin{exercise}
\label{prob:8-25}


\uses{prob:7-2}
8-25. Prove that if $G$ is an abelian Lie group, then $\operatorname{Lie}\left( G\right)$ is abelian. [Hint: show that the inversion map $i : G \rightarrow  G$ is a group homomorphism, and use Problem 7-2.]
\end{exercise}

